content:
/* ==========================================================================
   精密リアルタイム・アナログクロック スタイルシート
   ========================================================================== */

:root {
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-serif: "Georgia", "Cambria", "Times New Roman", serif;
  --font-mono: "SF Mono", "Consolas", "Courier New", monospace;
  --transition-smooth: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  --clock-size: min(340px, 80vw);
}

/* リセット & 基本設定 */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-sans);
  min-height: 100vh;
  background-color: #f1f5f9;
  color: #1e293b;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* アプリケーション全体コンテナ */
.clock-app-container {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 2rem 1rem;
  transition: background-color 0.4s ease, color 0.4s ease;
}

/* メインカード */
.clock-card {
  width: 100%;
  max-width: 540px;
  border-radius: 24px;
  padding: 2.25rem 2rem;
  box-shadow: 0 20px 40px -15px rgba(0, 0, 0, 0.12), 0 0 1px 1px rgba(0, 0, 0, 0.05);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.75rem;
  transition: var(--transition-smooth);
}

/* ヘッダーエリア */
.clock-header {
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  width: 100%;
}

.clock-title {
  font-size: 1.65rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.clock-desc {
  font-size: 0.875rem;
  opacity: 0.75;
}

/* ==========================================================================
   テーマ定義 (モダン, クラシック, ダーク)
   ========================================================================== */

/* --- モダンテーマ (デフォルト) --- */
.theme-modern.clock-app-container {
  background-color: #f8fafc;
}

.theme-modern .clock-card {
  background: #ffffff;
  color: #0f172a;
  border: 1px solid #e2e8f0;
}

.theme-modern .clock-face {
  background: radial-gradient(circle, #ffffff 60%, #f1f5f9 100%);
  box-shadow:
    inset 0 2px 6px rgba(0, 0, 0, 0.06),
    0 16px 32px rgba(15, 23, 42, 0.08),
    0 0 0 10px #f8fafc,
    0 0 0 11px #cbd5e1;
}

.theme-modern .clock-hour-mark {
  stroke: #334155;
  stroke-width: 3.5;
}

.theme-modern .clock-minute-mark {
  stroke: #94a3b8;
  stroke-width: 1.5;
}

.theme-modern .clock-number {
  fill: #1e293b;
  font-weight: 600;
  font-family: var(--font-sans);
}

.theme-modern .clock-brand-label {
  fill: #64748b;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-anchor: middle;
}

.theme-modern .hand-hour {
  stroke: #0f172a;
  stroke-width: 6;
}

.theme-modern .hand-minute {
  stroke: #334155;
  stroke-width: 4;
}

.theme-modern .hand-second,
.theme-modern .hand-second-tail {
  stroke: #ef4444;
  stroke-width: 2;
}

.theme-modern .clock-center-pin {
  fill: #ef4444;
  stroke: #ffffff;
  stroke-width: 2.5;
}

/* --- クラシックテーマ --- */
.theme-classic.clock-app-container {
  background-color: #f7f3ed;
}

.theme-classic .clock-card {
  background: #fffdf9;
  color: #382d23;
  border: 1px solid #e7ded0;
  box-shadow: 0 20px 45px -12px rgba(92, 64, 45, 0.15);
}

.theme-classic .clock-face {
  background: radial-gradient(circle, #fffdf8 55%, #f4ede1 100%);
  box-shadow:
    inset 0 3px 8px rgba(92, 64, 45, 0.12),
    0 16px 36px rgba(92, 64, 45, 0.14),
    0 0 0 10px #eadecd,
    0 0 0 12px #cbbba5;
}

.theme-classic .clock-hour-mark {
  stroke: #423023;
  stroke-width: 3.5;
}

.theme-classic .clock-minute-mark {
  stroke: #a38f7b;
  stroke-width: 1.5;
}

.theme-classic .clock-number {
  fill: #2c1e14;
  font-weight: 700;
  font-family: var(--font-serif);
}

.theme-classic .clock-brand-label {
  fill: #856a54;
  font-size: 8.5px;
  font-family: var(--font-serif);
  font-weight: 600;
  letter-spacing: 0.25em;
  text-anchor: middle;
}

.theme-classic .hand-hour {
  stroke: #2c1e14;
  stroke-width: 5.5;
}

.theme-classic .hand-minute {
  stroke: #4a382a;
  stroke-width: 3.8;
}

.theme-classic .hand-second,
.theme-classic .hand-second-tail {
  stroke: #b9770e;
  stroke-width: 1.8;
}

.theme-classic .clock-center-pin {
  fill: #b9770e;
  stroke: #fffbf2;
  stroke-width: 2.5;
}

/* --- ダークテーマ --- */
.theme-dark.clock-app-container {
  background-color: #090d16;
}

.theme-dark .clock-card {
  background: #111827;
  color: #f3f4f6;
  border: 1px solid #1f2937;
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.6);
}

.theme-dark .clock-face {
  background: radial-gradient(circle, #1a2234 45%, #0f1523 100%);
  box-shadow:
    inset 0 3px 12px rgba(0, 0, 0, 0.5),
    0 20px 40px rgba(0, 0, 0, 0.4),
    0 0 0 10px #111827,
    0 0 0 11px #374151;
}

.theme-dark .clock-hour-mark {
  stroke: #60a5fa;
  stroke-width: 3.5;
}

.theme-dark .clock-minute-mark {
  stroke: #475569;
  stroke-width: 1.5;
}

.theme-dark .clock-number {
  fill: #f1f5f9;
  font-weight: 600;
  font-family: var(--font-sans);
}

.theme-dark .clock-brand-label {
  fill: #38bdf8;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-anchor: middle;
}

.theme-dark .hand-hour {
  stroke: #e2e8f0;
  stroke-width: 6;
}

.theme-dark .hand-minute {
  stroke: #93c5fd;
  stroke-width: 4;
}

.theme-dark .hand-second,
.theme-dark .hand-second-tail {
  stroke: #38bdf8;
  stroke-width: 2;
}

.theme-dark .clock-center-pin {
  fill: #38bdf8;
  stroke: #0f172a;
  stroke-width: 2.5;
}

/* ==========================================================================
   アナログ時計 盤面 & 針
   ========================================================================== */

.analog-clock-wrapper {
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 0.5rem;
}

.clock-face {
  width: var(--clock-size);
  height: var(--clock-size);
  border-radius: 50%;
  position: relative;
  transition: background 0.4s ease, box-shadow 0.4s ease;
  user-select: none;
}

.clock-face-svg {
  width: 100%;
  height: 100%;
  display: block;
  overflow: visible;
}

.clock-hour-mark,
.clock-minute-mark {
  stroke-linecap: round;
}

.clock-number {
  font-size: 19px;
  text-anchor: middle;
  dominant-baseline: central;
}

/* 針の共通スタイル */
.clock-hand {
  stroke-linecap: round;
}

.clock-center-pin {
  r: 5.5;
}

/* ==========================================================================
   デジタル表示カード
   ========================================================================== */

.digital-display-card {
  width: 100%;
  background: rgba(125, 140, 160, 0.08);
  border-radius: 16px;
  padding: 1.1rem 1.25rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.4rem;
  border: 1px solid rgba(125, 140, 160, 0.15);
  backdrop-filter: blur(8px);
  text-align: center;
  transition: var(--transition-smooth);
}

.digital-time {
  font-family: var(--font-mono);
  font-size: 2.25rem;
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: 0.04em;
  font-variant-numeric: tabular-nums;
}

.digital-date {
  font-size: 0.95rem;
  font-weight: 500;
  opacity: 0.85;
}

.digital-timezone {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  padding: 0.2rem 0.65rem;
  border-radius: 9999px;
  background: rgba(125, 140, 160, 0.15);
  margin-top: 0.15rem;
}

/* ==========================================================================
   コントロールパネル & 設定UI
   ========================================================================== */

.controls-panel {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 1.1rem;
  padding-top: 0.25rem;
  border-top: 1px solid rgba(125, 140, 160, 0.15);
}

.control-group {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.control-label {
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  opacity: 0.75;
}

/* ボタン切り替えボタングループ */
.btn-group {
  display: flex;
  gap: 0.5rem;
  width: 100%;
  background: rgba(125, 140, 160, 0.08);
  padding: 0.3rem;
  border-radius: 12px;
}

.btn-toggle {
  flex: 1;
  border: none;
  background: transparent;
  color: inherit;
  padding: 0.6rem 0.5rem;
  font-size: 0.85rem;
  font-weight: 600;
  border-radius: 9px;
  cursor: pointer;
  transition: var(--transition-smooth);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  white-space: nowrap;
}

.btn-toggle:hover:not(.btn-active) {
  background: rgba(125, 140, 160, 0.12);
}

.theme-modern .btn-active {
  background: #0f172a;
  color: #ffffff;
  box-shadow: 0 4px 10px rgba(15, 23, 42, 0.18);
}

.theme-classic .btn-active {
  background: #382d23;
  color: #fffdf9;
  box-shadow: 0 4px 10px rgba(56, 45, 35, 0.2);
}

.theme-dark .btn-active {
  background: #3b82f6;
  color: #ffffff;
  box-shadow: 0 4px 12px rgba(59, 130, 246, 0.35);
}

/* タイムゾーン セレクトボックス */
.select-timezone {
  width: 100%;
  padding: 0.65rem 0.9rem;
  font-size: 0.9rem;
  font-family: inherit;
  border-radius: 12px;
  background: rgba(125, 140, 160, 0.08);
  color: inherit;
  border: 1px solid rgba(125, 140, 160, 0.25);
  cursor: pointer;
  outline: none;
  transition: var(--transition-smooth);
  appearance: auto;
}

.select-timezone:focus {
  border-color: #3b82f6;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.2);
}

.theme-dark .select-timezone option {
  background-color: #1f2937;
  color: #f3f4f6;
}

.theme-modern .select-timezone option,
.theme-classic .select-timezone option {
  background-color: #ffffff;
  color: #1e293b;
}

/* ==========================================================================
   レスポンシブ対応
   ========================================================================== */

@media (max-width: 480px) {
  :root {
    --clock-size: 260px;
  }

  .clock-card {
    padding: 1.5rem 1.15rem;
    gap: 1.25rem;
    border-radius: 20px;
  }

  .clock-title {
    font-size: 1.4rem;
  }

  .digital-time {
    font-size: 1.9rem;
  }

  .btn-toggle {
    font-size: 0.78rem;
    padding: 0.5rem 0.25rem;
  }
}

/**
 * 精密リアルタイム・アナログクロック 型定義ファイル
 */

export type ClockTheme = 'modern' | 'classic' | 'dark';

export type HandMovement = 'sweep' | 'step';

export interface TimeZoneOption {
  id: string;
  label: string;
  timeZone: string;
}

export interface ClockSettings {
  theme: ClockTheme;
  movement: HandMovement;
  showDigital: boolean;
  timeZone: string;
}

export interface AnalogClockProps {
  currentTime: Date;
  movement: HandMovement;
  theme: ClockTheme;
}

export interface ClockControlsProps {
  settings: ClockSettings;
  onUpdateSettings: (newSettings: Partial<ClockSettings>) => void;
}

import { useMemo } from 'react';
import { AnalogClockProps } from '../types';

export default function AnalogClock({ currentTime, movement, theme }: AnalogClockProps) {
  // 角度計算 (ミリ秒を含めた高精度計算)
  const { hourAngle, minuteAngle, secondAngle } = useMemo(() => {
    const hours = currentTime.getHours() % 12;
    const minutes = currentTime.getMinutes();
    const seconds = currentTime.getSeconds();
    const milliseconds = currentTime.getMilliseconds();

    let secVal = seconds;
    if (movement === 'sweep') {
      secVal = seconds + milliseconds / 1000;
    }
    const secAngle = secVal * 6; // 360 / 60

    let minVal = minutes;
    if (movement === 'sweep') {
      minVal = minutes + secVal / 60;
    } else {
      minVal = minutes + seconds / 60;
    }
    const minAngle = minVal * 6; // 360 / 60

    const hrVal = hours + minVal / 60;
    const hrAngle = hrVal * 30; // 360 / 12

    return {
      hourAngle: hrAngle,
      minuteAngle: minAngle,
      secondAngle: secAngle,
    };
  }, [currentTime, movement]);

  // 目盛りと数字の生成
  const clockTicks = useMemo(() => {
    const ticks = [];
    for (let i = 0; i < 60; i++) {
      const isHour = i % 5 === 0;
      const angle = (i * 6 * Math.PI) / 180;
      const rOuter = 95;
      const rInner = isHour ? 82 : 89;

      const x1 = 100 + rOuter * Math.sin(angle);
      const y1 = 100 - rOuter * Math.cos(angle);
      const x2 = 100 + rInner * Math.sin(angle);
      const y2 = 100 - rInner * Math.cos(angle);

      ticks.push({
        key: `tick-${i}`,
        x1,
        y1,
        x2,
        y2,
        isHour,
      });
    }
    return ticks;
  }, []);

  const clockNumbers = useMemo(() => {
    const numbers = [];
    const rNumber = 68;
    for (let num = 1; num <= 12; num++) {
      const angle = (num * 30 * Math.PI) / 180;
      const x = 100 + rNumber * Math.sin(angle);
      const y = 100 - rNumber * Math.cos(angle);
      numbers.push({
        num,
        x,
        y,
      });
    }
    return numbers;
  }, []);

  const brandText = theme === 'classic' ? 'CHRONOMETER' : theme === 'dark' ? 'PRECISION' : 'AUTOMATIC';

  return (
    <div className="analog-clock-wrapper">
      <div className="clock-face">
        <svg
          className="clock-face-svg"
          viewBox="0 0 200 200"
          xmlns="http://www.w3.org/2000/svg"
        >
          {/* 目盛り */}
          {clockTicks.map((tick) => (
            <line
              key={tick.key}
              x1={tick.x1}
              y1={tick.y1}
              x2={tick.x2}
              y2={tick.y2}
              className={tick.isHour ? 'clock-hour-mark' : 'clock-minute-mark'}
            />
          ))}

          {/* ブランド/シリーズロゴ表示 */}
          <text x="100" y="66" className="clock-brand-label">
            {brandText}
          </text>

          {/* 1〜12の文字盤数字 */}
          {clockNumbers.map(({ num, x, y }) => (
            <text
              key={`num-${num}`}
              x={x}
              y={y}
              className="clock-number"
            >
              {num}
            </text>
          ))}

          {/* 時針 */}
          <line
            x1="100"
            y1="100"
            x2="100"
            y2="48"
            className="clock-hand hand-hour"
            transform={`rotate(${hourAngle} 100 100)`}
          />

          {/* 分針 */}
          <line
            x1="100"
            y1="100"
            x2="100"
            y2="28"
            className="clock-hand hand-minute"
            transform={`rotate(${minuteAngle} 100 100)`}
          />

          {/* 秒針の尻尾 (カウンターウェイト) */}
          <line
            x1="100"
            y1="100"
            x2="100"
            y2="118"
            className="clock-hand hand-second-tail"
            transform={`rotate(${secondAngle} 100 100)`}
          />

          {/* 秒針 */}
          <line
            x1="100"
            y1="100"
            x2="100"
            y2="20"
            className="clock-hand hand-second"
            transform={`rotate(${secondAngle} 100 100)`}
          />

          {/* センターピン */}
          <circle cx="100" cy="100" className="clock-center-pin" />
        </svg>
      </div>
    </div>
  );
}

import { ClockControlsProps, ClockTheme, HandMovement, TimeZoneOption } from '../types';

const TIMEZONE_OPTIONS: TimeZoneOption[] = [
  { id: 'asia-tokyo', label: '東京 (JST, UTC+9)', timeZone: 'Asia/Tokyo' },
  { id: 'europe-london', label: 'ロンドン (GMT/BST, UTC+0/+1)', timeZone: 'Europe/London' },
  { id: 'america-new_york', label: 'ニューヨーク (EST/EDT, UTC-5/-4)', timeZone: 'America/New_York' },
  { id: 'europe-paris', label: 'パリ (CET/CEST, UTC+1/+2)', timeZone: 'Europe/Paris' },
  { id: 'australia-sydney', label: 'シドニー (AEST/AEDT, UTC+10/+11)', timeZone: 'Australia/Sydney' },
];

export default function ClockControls({ settings, onUpdateSettings }: ClockControlsProps) {
  const handleThemeChange = (theme: ClockTheme) => {
    onUpdateSettings({ theme });
  };

  const handleMovementChange = (movement: HandMovement) => {
    onUpdateSettings({ movement });
  };

  const handleDigitalToggle = (showDigital: boolean) => {
    onUpdateSettings({ showDigital });
  };

  const handleTimeZoneChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    onUpdateSettings({ timeZone: e.target.value });
  };

  return (
    <div className="controls-panel">
      {/* テーマ選択 */}
      <div className="control-group">
        <label className="control-label">テーマ</label>
        <div className="btn-group">
          <button
            type="button"
            className={`btn-toggle ${settings.theme === 'modern' ? 'btn-active' : ''}`}
            onClick={() => handleThemeChange('modern')}
          >
            モダン
          </button>
          <button
            type="button"
            className={`btn-toggle ${settings.theme === 'classic' ? 'btn-active' : ''}`}
            onClick={() => handleThemeChange('classic')}
          >
            クラシック
          </button>
          <button
            type="button"
            className={`btn-toggle ${settings.theme === 'dark' ? 'btn-active' : ''}`}
            onClick={() => handleThemeChange('dark')}
          >
            ダーク
          </button>
        </div>
      </div>

      {/* 運針方式 (秒針) */}
      <div className="control-group">
        <label className="control-label">秒針の動き</label>
        <div className="btn-group">
          <button
            type="button"
            className={`btn-toggle ${settings.movement === 'sweep' ? 'btn-active' : ''}`}
            onClick={() => handleMovementChange('sweep')}
          >
            スイープ（滑らか）
          </button>
          <button
            type="button"
            className={`btn-toggle ${settings.movement === 'step' ? 'btn-active' : ''}`}
            onClick={() => handleMovementChange('step')}
          >
            ステップ（1秒刻み）
          </button>
        </div>
      </div>

      {/* デジタル時計表示切り替え */}
      <div className="control-group">
        <label className="control-label">デジタル表示</label>
        <div className="btn-group">
          <button
            type="button"
            className={`btn-toggle ${settings.showDigital ? 'btn-active' : ''}`}
            onClick={() => handleDigitalToggle(true)}
          >
            表示する
          </button>
          <button
            type="button"
            className={`btn-toggle ${!settings.showDigital ? 'btn-active' : ''}`}
            onClick={() => handleDigitalToggle(false)}
          >
            非表示
          </button>
        </div>
      </div>

      {/* タイムゾーン選択 */}
      <div className="control-group">
        <label className="control-label" htmlFor="timezone-select">タイムゾーン</label>
        <select
          id="timezone-select"
          className="select-timezone"
          value={settings.timeZone}
          onChange={handleTimeZoneChange}
        >
          {TIMEZONE_OPTIONS.map((opt) => (
            <option key={opt.id} value={opt.timeZone}>
              {opt.label}
            </option>
          ))}
        </select>
      </div>
    </div>
  );
}

import { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { ClockSettings } from './types';
import AnalogClock from './components/AnalogClock';
import ClockControls from './components/ClockControls';

/**
 * タイムゾーンに応じたDateオブジェクトを生成するユーティリティ
 */
function getZonedDate(targetTimeZone: string): Date {
  const now = new Date();
  try {
    const formatter = new Intl.DateTimeFormat('en-US', {
      timeZone: targetTimeZone,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      fractionalSecondDigits: 3,
      hour12: false,
    });

    const parts = formatter.formatToParts(now);
    const dateMap: { [key: string]: string } = {};
    for (const part of parts) {
      dateMap[part.type] = part.value;
    }

    const year = parseInt(dateMap.year, 10);
    const month = parseInt(dateMap.month, 10) - 1;
    const day = parseInt(dateMap.day, 10);
    const hour = parseInt(dateMap.hour, 10);
    const minute = parseInt(dateMap.minute, 10);
    const second = parseInt(dateMap.second, 10);
    const millisecond = parseInt(dateMap.fractionalSecond || '0', 10);

    return new Date(year, month, day, hour, minute, second, millisecond);
  } catch {
    return now;
  }
}

export default function App() {
  const [settings, setSettings] = useState<ClockSettings>({
    theme: 'modern',
    movement: 'sweep',
    showDigital: true,
    timeZone: 'Asia/Tokyo',
  });

  const [currentTime, setCurrentTime] = useState<Date>(() => getZonedDate(settings.timeZone));
  const reqIdRef = useRef<number | null>(null);

  // requestAnimationFrame による高精度なリアルタイムレンダリング
  const updateLoop = useCallback(() => {
    setCurrentTime(getZonedDate(settings.timeZone));
    reqIdRef.current = requestAnimationFrame(updateLoop);
  }, [settings.timeZone]);

  useEffect(() => {
    reqIdRef.current = requestAnimationFrame(updateLoop);
    return () => {
      if (reqIdRef.current !== null) {
        cancelAnimationFrame(reqIdRef.current);
      }
    };
  }, [updateLoop]);

  const handleUpdateSettings = (newSettings: Partial<ClockSettings>) => {
    setSettings((prev) => ({
      ...prev,
      ...newSettings,
    }));
  };

  // デジタルフォーマット
  const digitalInfo = useMemo(() => {
    const hours = String(currentTime.getHours()).padStart(2, '0');
    const minutes = String(currentTime.getMinutes()).padStart(2, '0');
    const seconds = String(currentTime.getSeconds()).padStart(2, '0');

    const year = currentTime.getFullYear();
    const month = String(currentTime.getMonth() + 1).padStart(2, '0');
    const date = String(currentTime.getDate()).padStart(2, '0');
    const dayNames = ['日曜日', '月曜日', '火曜日', '水曜日', '木曜日', '金曜日', '土曜日'];
    const dayStr = dayNames[currentTime.getDay()];

    return {
      time: `${hours}:${minutes}:${seconds}`,
      date: `${year}年${month}月${date}日 (${dayStr})`,
    };
  }, [currentTime]);

  const themeClass = `theme-${settings.theme}`;

  return (
    <div className={`clock-app-container ${themeClass}`}>
      <main className="clock-card">
        {/* ヘッダー */}
        <header className="clock-header">
          <h1 className="clock-title">リアルタイム・高精度クロック</h1>
          <p className="clock-desc">スイープ運針と世界の標準時に対応した精密アナログ時計</p>
        </header>

        {/* アナログ時計盤面 */}
        <AnalogClock
          currentTime={currentTime}
          movement={settings.movement}
          theme={settings.theme}
        />

        {/* デジタル同時表示カード */}
        {settings.showDigital && (
          <section className="digital-display-card" aria-label="デジタル時計表示">
            <div className="digital-time">{digitalInfo.time}</div>
            <div className="digital-date">{digitalInfo.date}</div>
            <div className="digital-timezone">{settings.timeZone}</div>
          </section>
        )}

        {/* 設定コントロール */}
        <ClockControls
          settings={settings}
          onUpdateSettings={handleUpdateSettings}
        />
      </main>
    </div>
  );
}
